                    @close="showEmojiPicker = false"
                />
              </div>
            </div>
            <button
              @click="addNewTweet"
              type="button"
              class="h-10 px-4 text-white font-semibold bg-blue hover:bg-darkblue rounded-full"
              :class="(tweet.text.trim() && pendingReads === 0 && !posting && !videoUploading && pollReady && sponsoredReady) ? '' : 'opacity-50 cursor-not-allowed'"
              :disabled="!tweet.text.trim() || pendingReads > 0 || posting || videoUploading || !pollReady || !sponsoredReady"
              :title="videoUploading ? 'Uploading video…' : (pendingReads > 0 ? 'Uploading image…' : (!pollReady ? 'Fill in every poll choice' : (!sponsoredReady ? 'Set a price for the sponsored tweet' : '')))"
            >
              <span v-if="!posting">Tweet</span>
              <span v-else><i class="fas fa-circle-notch fa-spin mr-1" aria-hidden="true"></i>Posting…</span>
            </button>
          </div>
        </div>
        <input
            v-show="showFileDropInput"
            ref="dropFileInput"
            type="file"
            multiple
            tabindex="-1"
            aria-hidden="true"
            class="absolute inset-0 w-full h-full opacity-0 z-10"
            @dragover.stop
            @dragleave="showFileDropInput = false"
            @drop.stop="onDropFileInputDrop"
            @change="dropFileInputChange"
        />
      </div>

      <!-- timeline -->
      <Loader :loading="loading" />
      <div
        v-if="!loading && timeline.length === 0"
        class="flex flex-col items-center justify-center w-full pt-10 px-6"
      >
        <p class="font-bold text-lg">Welcome to Warpnet!</p>
        <p class="text-sm text-dark text-center">
          This is the best place to see what's happening in your world. Find
          some people and topics to follow now.
        </p>
        <button
          @click="showImportModal = true"
          class="text-white bg-blue rounded-full font-semibold mt-4 px-4 py-2 hover:bg-darkblue"
        >
          <p class="hidden lg:block">Import tweets from X</p>
          <i class="fas fa-file-import lg:hidden"></i>
        </button>
      </div>
      <Tweets :tweets="timeline" />
      <div v-if="loadingMore" class="py-4 flex justify-center text-dark" role="status" aria-label="Loading more">
        <i class="fas fa-circle-notch fa-spin" aria-hidden="true"></i>
      </div>
      <div v-else-if="endOfFeed && timeline.length > 0" class="py-4 text-center text-sm text-dark">
        You're all caught up.
      </div>
    </div>
    <InfoOverlay
        :visible="showInfo"
        :content="infoContent"
        :position="infoPosition"
    />
    <!-- default right bar -->
    <DefaultRightBar
        :profile="profile"
